CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql SET search_path = public AS $$ SELECT nullif(current_setting('app.uid',true),'')::uuid $$;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql SET search_path = public AS $$ SELECT 'authenticated'::text $$;
CREATE TABLE profiles(id uuid PRIMARY KEY, test_streak int DEFAULT 0);
CREATE TABLE role_assignments(user_id uuid, role text, status text, approver_id uuid, start_date date);
CREATE TABLE quiz_sessions(id uuid PRIMARY KEY,quiz_type text,session_date date DEFAULT current_date,title text,status text DEFAULT 'live',live_opens_at timestamptz DEFAULT now()-interval '1 hour',live_closes_at timestamptz DEFAULT now()+interval '1 hour',created_at timestamptz DEFAULT now(),reward_perfect int DEFAULT 6000,reward_partial int DEFAULT 1000);
CREATE TABLE quiz_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, quiz_session_id uuid, status text DEFAULT 'in_progress', talents_scored int DEFAULT 0,highest_question_reached int DEFAULT 0,submitted_at timestamptz,relics_used jsonb DEFAULT '[]');
CREATE TABLE game_attempts(user_id uuid,score int);
CREATE TABLE arena_participants(user_id uuid,score int);
CREATE TABLE relic_types(id uuid,slug text);
CREATE TABLE relic_inventory(id uuid,user_id uuid,relic_type_id uuid,quantity int,source_description text, UNIQUE(user_id,relic_type_id));
CREATE TABLE automatic_sentry_grants(user_id uuid,grant_key text, UNIQUE(user_id,grant_key));
CREATE TABLE streak_freezers(user_id uuid,freezer_type text,source text);
CREATE TABLE generated_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quiz_session_id uuid,question_payload jsonb,difficulty_tag text DEFAULT 'easy');
CREATE TABLE question_responses(question_id uuid,quiz_attempt_id uuid,answer jsonb,assisted_by_relic boolean DEFAULT false, UNIQUE(question_id,quiz_attempt_id));
CREATE TABLE relic_usage_log(user_id uuid,quiz_attempt_id uuid,relic_type_id uuid,effect_applied text);
CREATE TABLE denarii_ledger_entries(user_id uuid,amount int,source_type text,source_reference text,description text);
CREATE TABLE daily_records(user_id uuid,record_date date,day_type text,quiz_attempt_id uuid,streak_valid boolean, UNIQUE(user_id,record_date));
CREATE TABLE weekly_quiz_result_releases(attempt_id uuid UNIQUE,user_id uuid,quiz_session_id uuid,correct_count int,question_count int,figs_earned int,perfect boolean,denarii_award int,release_at timestamptz,released_at timestamptz);
CREATE FUNCTION is_instructor(p_user_id uuid) RETURNS boolean LANGUAGE sql SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM role_assignments WHERE user_id=p_user_id AND role='instructor' AND status='active') $$;
CREATE FUNCTION compute_strict_streak(p_user_id uuid) RETURNS TABLE(current_streak int) LANGUAGE sql SET search_path = public AS $$ SELECT test_streak FROM profiles WHERE id=p_user_id $$;
CREATE FUNCTION quiz_answer_is_correct(answer jsonb,payload jsonb) RETURNS boolean LANGUAGE sql SET search_path = public AS $$ SELECT coalesce(answer#>>'{}'=payload->>'correct_answer',false) $$;
CREATE FUNCTION notify_user(uuid,uuid,text,text,text,text,jsonb) RETURNS void LANGUAGE sql SET search_path = public AS $$ SELECT $$;
CREATE FUNCTION release_due_weekly_quiz_results(uuid) RETURNS void LANGUAGE sql SET search_path = public AS $$ SELECT $$;
INSERT INTO profiles SELECT ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,100 FROM generate_series(1,8) n;
INSERT INTO role_assignments SELECT id, CASE WHEN id::text LIKE '%000000000008' THEN 'sentry' ELSE 'cadet' END,'active',null,current_date FROM profiles;
INSERT INTO game_attempts SELECT id,10001 FROM profiles;
